-- GOOD TIMES / MCP Gateway ONLY. Additive INTERNAL commercial staging. Not a public product or a checkout enablement.
-- Target project dzlmtvodpyhetvektfuo. Do not run against the consumer GOOD TIMES project.
create table if not exists public.gt_partner_rate_cards (
  id uuid primary key default gen_random_uuid(),
  brand_key text not null default 'GOOD_TIMES' check (brand_key = 'GOOD_TIMES'),
  market_key text not null default 'atlanta' check (market_key = 'atlanta'),
  version_tag text not null,
  currency text not null default 'USD' check (currency = 'USD'),
  lifecycle text not null default 'internal_draft' check(lifecycle in ('internal_draft','owner_review','internally_locked')),
  public_visible boolean not null default false check (public_visible = false),
  checkout_enabled boolean not null default false check (checkout_enabled = false),
  description text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(brand_key,market_key,version_tag)
);
create table if not exists public.gt_partner_commercial_offers (
  id uuid primary key default gen_random_uuid(),
  rate_card_id uuid not null references public.gt_partner_rate_cards(id) on delete restrict,
  offer_key text not null,
  offer_type text not null check (offer_type in ('standard_placement','premium_sponsorship','trade_private','technical_surface','new_service','bundle')),
  channel text not null,
  title text not null,
  internal_list_price_cents integer check(internal_list_price_cents > 0),
  pricing_unit text not null,
  legacy_source text not null,
  legacy_key text,
  legacy_price_cents integer check(legacy_price_cents > 0),
  review_status text not null check(review_status in ('hold_surface_qa','hold_channel_qa','hold_cost_qa','trade_private','unpriced_technical')),
  public_visible boolean not null default false check(public_visible = false),
  checkout_enabled boolean not null default false check(checkout_enabled = false),
  delivery_verified boolean not null default false check(delivery_verified = false),
  deliverables jsonb not null default '[]'::jsonb check(jsonb_typeof(deliverables)='array'),
  proof_requirements jsonb not null default '[]'::jsonb check(jsonb_typeof(proof_requirements)='array'),
  notes text not null default '',
  metadata jsonb not null default '{}'::jsonb check(jsonb_typeof(metadata)='object'),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(rate_card_id,offer_key)
);
comment on table public.gt_partner_rate_cards is 'GOOD TIMES Atlanta internal-only versioned commercial rate card. No checkout/public release permitted by schema. Action 2 (2026-10-09).';
comment on table public.gt_partner_commercial_offers is 'Internal price proposals and source mappings; never interpret as sellable or production inventory until capacity and channel receipts verified.';
alter table public.gt_partner_rate_cards enable row level security;
alter table public.gt_partner_commercial_offers enable row level security;
revoke all on table public.gt_partner_rate_cards from public, anon, authenticated;
revoke all on table public.gt_partner_commercial_offers from public, anon, authenticated;
grant select,insert,update,delete on table public.gt_partner_rate_cards to service_role;
grant select,insert,update,delete on table public.gt_partner_commercial_offers to service_role;
-- No policies for anon/authenticated. Mutations must be server-only.
