insert into public.gt_partner_commercial_offers(rate_card_id,offer_key,offer_type,channel,title,internal_list_price_cents,pricing_unit,legacy_source,legacy_key,legacy_price_cents,review_status,deliverables,proof_requirements,notes,metadata)
select rc.id,s.offer_key,s.offer_type,s.channel,s.title,s.internal_list_price_cents,s.pricing_unit,s.legacy_source,s.legacy_key,s.legacy_price_cents,s.review_status,s.deliverables,s.proof_requirements,s.notes,s.metadata
from source_rows s join public.gt_partner_rate_cards rc on rc.brand_key='GOOD_TIMES' and rc.market_key='atlanta' and rc.version_tag='2026-10-09-v1'
on conflict(rate_card_id,offer_key) do nothing;
-- Pricing and inventory safety: public_visible=false, checkout_enabled=false, delivery_verified=false and restrictive CHECKs require an audited later migration before public rollout.
